// 4. 全域狀態
let audioUnlocked = false;
let currentMode = "keyboard";
let selectedVoice = null;
let synth = window.speechSynthesis;

let gameState = {
  currentQuestion: null,
  stars: 0,
  balloons: []
};

// 5. 語音合成引擎初始化
function initSpeech() {
  if (!synth) return;
  function setVoice() {
    const voices = synth.getVoices();
    // 優先尋找台灣繁體中文 (zh-TW) — iOS 上常見名稱：Meijia, Yating
    selectedVoice = voices.find(v =>
      v.lang === "zh-TW" ||
      v.name.includes("Meijia") ||
      v.name.includes("Yating") ||
      v.name.includes("Hanhan")
    );
    // 備用：任何中文語音
    if (!selectedVoice) {
      selectedVoice = voices.find(v => v.lang.startsWith("zh"));
    }
  }
  setVoice();
  if (synth.onvoiceschanged !== undefined) {
    synth.onvoiceschanged = setVoice;
  }
}

// 解鎖 iOS 語音 (需在使用者第一次點擊時執行)
function unlockAudio() {
  if (audioUnlocked) return;
  try {
    const u = new SpeechSynthesisUtterance(" ");
    u.volume = 0;
    synth.speak(u);
    audioUnlocked = true;
  } catch (e) {
    console.error("Failed to unlock audio:", e);
  }
}

// 語音發音 (promise-friendly, 自動重試)
function speak(text, callback) {
  if (!synth) return;
  synth.cancel();
  const utterance = new SpeechSynthesisUtterance(text);
  if (selectedVoice) utterance.voice = selectedVoice;
  utterance.lang = "zh-TW";
  utterance.rate = 0.82;
  utterance.pitch = 1.1;
  if (callback) utterance.onend = callback;
  synth.speak(utterance);
}

// 輔助：從聲調 symbol 取得顯示文字
function getToneDisplay(symbol) {
  const t = TONES.find(t => t.symbol === symbol);
  return t ? t.display : "?";
}

// ==========================================
// 模式 1：點讀鍵盤功能
// ==========================================
function renderKeyboard() {
  const container = document.getElementById("keyboard-grid");
  if (!container) return;
  container.innerHTML = "";

  const categories = {
    initial: { title: "聲母 (ㄅ—ㄙ)", class: "category-initial" },
    medial:  { title: "介音 (ㄧ ㄨ ㄩ)", class: "category-medial" },
    final:   { title: "韻母 (ㄚ—ㄦ)",  class: "category-final"   }
  };

  Object.keys(categories).forEach(cat => {
    const section = document.createElement("div");
    section.className = `keyboard-section ${categories[cat].class}`;
    const title = document.createElement("h3");
    title.innerText = categories[cat].title;
    section.appendChild(title);

    const keysContainer = document.createElement("div");
    keysContainer.className = "keys-container";

    Object.keys(ZHUYIN_DB).forEach(key => {
      const item = ZHUYIN_DB[key];
      if (item.category !== cat) return;

      const card = document.createElement("div");
      card.className = "zhuyin-card";
      card.style.backgroundColor = item.color;
      card.id = `card-${key}`;

      card.innerHTML = `
        <div class="card-inner">
          <div class="card-front" style="background-color: ${item.color}">
            <span class="symbol" style="color: ${item.textColor}">${key}</span>
            <button class="rhyme-btn" id="rhyme-${key}" title="聽口訣">🎵</button>
          </div>
          <div class="card-back" style="background-color: ${item.color}">
            <div class="back-svg">${item.svg}</div>
            <div class="back-word" style="color: ${item.textColor}">${item.word}</div>
            <div class="back-pinyin">${item.pinyin}</div>
          </div>
        </div>
      `;

      // 口訣按鈕：不觸發翻牌
      const rhymeBtn = card.querySelector(`#rhyme-${key}`);
      rhymeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        unlockAudio();
        speak(item.rhyme);
      });

      // 點擊卡片翻轉並發音
      card.addEventListener("click", () => {
        unlockAudio();
        card.classList.toggle("flipped");
        if (card.classList.contains("flipped")) {
          speak(`${key}。${item.word}`);
          setTimeout(() => card.classList.remove("flipped"), 4500);
        } else {
          speak(key);
        }
      });

      keysContainer.appendChild(card);
    });

    section.appendChild(keysContainer);
    container.appendChild(section);
  });
}

// ==========================================
// 模式 2：拼音機器人功能
// ==========================================
let robotState = { initial: "", medial: "", final: "", tone: "" };

function renderRobot() {
  renderRobotGroup("robot-initials", "initial", "btn-init");
  renderRobotGroup("robot-medials",  "medial",  "btn-med");
  renderRobotGroup("robot-finals",   "final",   "btn-fin");

  const toneGroup = document.getElementById("robot-tones");
  if (toneGroup) {
    toneGroup.innerHTML = `<button class="robot-btn empty-btn" onclick="selectRobotKey(\'tone\',\'\')">無</button>`;
    TONES.forEach(tone => {
      toneGroup.innerHTML += `<button class="robot-btn btn-tone" id="robot-tone-${tone.symbol}" onclick="selectRobotKey('tone','${tone.symbol}')">${tone.display}</button>`;
    });
  }
  // 預設選一聲
  selectRobotKey("tone", "");
  updateRobotDisplay();
}

function renderRobotGroup(containerId, category, btnClass) {
  const group = document.getElementById(containerId);
  if (!group) return;
  group.innerHTML = `<button class="robot-btn empty-btn" onclick="selectRobotKey('${category}','')">無</button>`;
  Object.keys(ZHUYIN_DB).forEach(key => {
    if (ZHUYIN_DB[key].category === category) {
      group.innerHTML += `<button class="robot-btn ${btnClass}" id="robot-key-${key}" onclick="selectRobotKey('${category}','${key}')">${key}</button>`;
    }
  });
}

function selectRobotKey(type, value) {
  unlockAudio();
  robotState[type] = value;

  if (value !== "") {
    if (type === "tone") {
      const toneObj = TONES.find(t => t.symbol === value);
      if (toneObj) speak(toneObj.audioText);
    } else {
      speak(value);
    }
  }

  // 更新按鈕高亮
  const containerMap = {
    initial: "robot-initials", medial: "robot-medials",
    final: "robot-finals", tone: "robot-tones"
  };
  const container = document.getElementById(containerMap[type]);
  if (container) {
    Array.from(container.getElementsByTagName("button")).forEach(btn => btn.classList.remove("active"));
    if (value === "") {
      container.getElementsByTagName("button")[0].classList.add("active");
    } else {
      const activeId = type === "tone" ? `robot-tone-${value}` : `robot-key-${value}`;
      const activeBtn = document.getElementById(activeId);
      if (activeBtn) activeBtn.classList.add("active");
    }
  }

  updateRobotDisplay();
}



function isValidZhuyin(init, med, fin) {
  if (init === '-' && med === '-' && fin === '-') return true;

  const palatals = ['ㄐ', 'ㄑ', 'ㄒ'];
  if (palatals.includes(init)) {
    if (med === '-' || med === 'ㄨ') return false;
  }

  const noYiYu = ['ㄍ', 'ㄎ', 'ㄏ', 'ㄓ', 'ㄔ', 'ㄕ', 'ㄖ', 'ㄗ', 'ㄘ', 'ㄙ'];
  if (noYiYu.includes(init)) {
    if (med === 'ㄧ' || med === 'ㄩ') return false;
  }

  const labials = ['ㄅ', 'ㄆ', 'ㄇ', 'ㄈ'];
  if (labials.includes(init)) {
    if (med === 'ㄩ') return false;
    if (init === 'ㄈ' && med === 'ㄧ') return false;
    if (med === 'ㄨ' && fin !== '-') return false;
  }

  if ((init === 'ㄉ' || init === 'ㄊ') && med === 'ㄩ') return false;

  if (med === 'ㄧ' && ['ㄛ', 'ㄨ'].includes(fin)) return false;
  if (med === 'ㄨ' && ['ㄝ', 'ㄩ'].includes(fin)) return false;
  if (med === 'ㄩ' && ['ㄜ', 'ㄞ', 'ㄟ', 'ㄠ', 'ㄡ', 'ㄨ'].includes(fin)) return false;

  return true;
}

function filterRobotOptions() {
  const init = robotState.initial || '-';
  const med = robotState.medial || '-';
  const fin = robotState.final || '-';

  document.querySelectorAll('#robot-initials .robot-btn:not(.empty-btn)').forEach(btn => {
    const key = btn.id.replace('robot-key-', '');
    const isValid = isValidZhuyin(key, med, fin);
    btn.classList.toggle('disabled', !isValid);
  });

  document.querySelectorAll('#robot-medials .robot-btn:not(.empty-btn)').forEach(btn => {
    const key = btn.id.replace('robot-key-', '');
    const isValid = isValidZhuyin(init, key, fin);
    btn.classList.toggle('disabled', !isValid);
  });

  document.querySelectorAll('#robot-finals .robot-btn:not(.empty-btn)').forEach(btn => {
    const key = btn.id.replace('robot-key-', '');
    const isValid = isValidZhuyin(init, med, key);
    btn.classList.toggle('disabled', !isValid);
  });
}

function updateRobotDisplay() {
  filterRobotOptions();
  const init = robotState.initial || "-";
  const med  = robotState.medial  || "-";
  const fin  = robotState.final   || "-";
  const tone = robotState.tone    || "1";
  const toneObj = TONES.find(t => t.symbol === tone);
  const toneDisplayChar = toneObj ? toneObj.display : "";

  // 更新 4 個顯示槽
  document.getElementById("robot-display-initial").innerText = robotState.initial || " ";
  document.getElementById("robot-display-medial").innerText  = robotState.medial  || " ";
  document.getElementById("robot-display-final").innerText   = robotState.final   || " ";
  document.getElementById("robot-display-tone").innerText    = toneDisplayChar;

  // 組合注音文字（用於螢幕顯示，聲調符號加在最後一個注音右上角）
  const phonetic = (robotState.initial || "") + (robotState.medial || "") + (robotState.final || "");
  const phoneticDisplay = phonetic ? (phonetic + (toneDisplayChar !== "一聲" ? toneDisplayChar : "")) : "";

  const combinationKey = `${init}|${med}|${fin}|${tone}`;
  const dictItem = SPELLING_DICT[combinationKey];
  const screen = document.getElementById("robot-screen");

  if (dictItem) {
    // 有查到對應的中文字：顯示字、插圖和例詞
    screen.innerHTML = `
      <div class="result-phonetic">${phoneticDisplay}</div>
      <div class="result-word">${dictItem.word}</div>
      <div class="result-svg">${dictItem.svg}</div>
      <div class="result-detail">${dictItem.detail}</div>
    `;
    screen.classList.add("has-result");
  } else if (phonetic) {
    // 沒查到字典，但已有輸入：顯示注音組合文字 + 鼓勵發音
    screen.innerHTML = `
      <div class="result-phonetic big-phonetic">${phoneticDisplay}</div>
      <div class="result-hint">
        <span class="hint-icon">🤖</span>
        <span>按下方按鈕<br>聽聽怎麼唸！</span>
      </div>
    `;
    screen.classList.remove("has-result");
  } else {
    // 完全沒有選擇：顯示引導
    screen.innerHTML = `
      <div class="robot-idle-icon">🤖</div>
      <div class="result-detail">從左邊選注音<br>機器人來拼音！</div>
    `;
    screen.classList.remove("has-result");
  }
}

function startRobotSpelling() {
  unlockAudio();
  const init = robotState.initial;
  const med  = robotState.medial;
  const fin  = robotState.final;
  const tone = robotState.tone || "1";

  if (!init && !med && !fin) {
    speak("請先選擇注音符號喔！");
    return;
  }

  const toneObj  = TONES.find(t => t.symbol === tone);
  const toneName = toneObj ? toneObj.audioText : "一聲";
  const initK    = init || "-";
  const medK     = med  || "-";
  const finK     = fin  || "-";
  const dictItem = SPELLING_DICT[`${initK}|${medK}|${finK}|${tone}`];
  const combined = (init || "") + (med || "") + (fin || "");

  // 機器人眼睛閃爍動畫
  const eyes = document.querySelectorAll(".eye");
  eyes.forEach(e => e.style.background = "#F59E0B");
  setTimeout(() => eyes.forEach(e => e.style.background = "#1F2937"), 600);

  // 在螢幕上顯示「正在發音...」動畫
  const screen = document.getElementById("robot-screen");
  const toneDisplayChar = toneObj ? toneObj.display : "";
  const phoneticDisplay = combined + (toneDisplayChar !== "一聲" ? toneDisplayChar : "");

  // 逐段高亮顯示：聲母 → 介音 → 韻母 → 結合音
  const readSeq = [];
  if (init) readSeq.push({ sound: init, label: `<span class="ph-init">${init}</span>` });
  if (med)  readSeq.push({ sound: med,  label: `<span class="ph-med">${med}</span>` });
  if (fin)  readSeq.push({ sound: fin,  label: `<span class="ph-fin">${fin}</span>` });

  let step = 0;
  function playNext() {
    if (step < readSeq.length) {
      // 高亮目前唸到哪個注音
      const highlighted = readSeq.map((r, i) =>
        i === step ? `<span class="ph-active">${r.sound}</span>` : `<span class="ph-dim">${r.sound}</span>`
      ).join("");
      screen.innerHTML = `
        <div class="result-phonetic anim-speaking">${highlighted}</div>
        <div class="result-detail">正在唸：${readSeq[step].sound}</div>
      `;
      speak(readSeq[step].sound, () => {
        step++;
        setTimeout(playNext, 300);
      });
    } else {
      // 全部唸完後：顯示合成音
      let finalWord = combined;
      if (dictItem) {
        finalWord = dictItem.word;
      } else {
        let pinyinKey = phoneticDisplay;
        if (tone === '0' && phoneticDisplay.endsWith('˙')) {
          pinyinKey = '˙' + combined;
        }
        if (FALLBACK_CHARS[pinyinKey]) {
          finalWord = FALLBACK_CHARS[pinyinKey];
        } else if (FALLBACK_CHARS[combined]) {
          finalWord = FALLBACK_CHARS[combined];
        }
      }
      screen.innerHTML = `
        <div class="result-phonetic result-phonetic-combined">${phoneticDisplay}</div>
        <div class="result-detail">➡ ${finalWord} !</div>
      `;
      speak(finalWord, () => {
        // 稍後顯示完整結果（若字典有對應圖片）
        setTimeout(() => {
          if (dictItem) {
            screen.innerHTML = `
              <div class="result-phonetic">${phoneticDisplay}</div>
              <div class="result-word">${dictItem.word}</div>
              <div class="result-svg">${dictItem.svg}</div>
              <div class="result-detail">${dictItem.detail}</div>
            `;
            screen.classList.add("has-result");
            speak(dictItem.detail);
          } else {
            screen.innerHTML = `
              <div class="result-phonetic big-phonetic">${phoneticDisplay}</div>
              <div class="result-hint">
                <span class="hint-icon">🤖</span>
                <span>拼出來了！<br>再試其他組合吧！</span>
              </div>
            `;
          }
          // 機器人眼睛變綠 (成功) 
          eyes.forEach(e => e.style.background = "#10B981");
          setTimeout(() => eyes.forEach(e => e.style.background = "#1F2937"), 1200);
        }, 600);
      });
    }
  }
  playNext();
}

// ==========================================
// 模式 3：問答挑戰遊戲
// ==========================================
function startBalloonGame() {
  unlockAudio();
  gameState.stars = 0;
  updateStars();
  nextBalloonQuestion();
}

function updateStars() {
  const c = document.getElementById("stars-container");
  if (c) c.innerHTML = "⭐".repeat(gameState.stars);
}

function nextBalloonQuestion() {
  document.getElementById("game-canvas-area").innerHTML = "";

  const questionType = Math.floor(Math.random() * 2); // 0: 聽音找符號, 1: 聽詞拼音
  const keys = Object.keys(ZHUYIN_DB);

  if (questionType === 0) {
    // 關卡一：聽音找注音符號
    const targetKey = keys[Math.floor(Math.random() * keys.length)];
    gameState.currentQuestion = { type: "find_key", answer: targetKey };

    speak(`請找到注音符號，${targetKey}`);

    const options = [targetKey];
    while (options.length < 4) {
      const rk = keys[Math.floor(Math.random() * keys.length)];
      if (!options.includes(rk)) options.push(rk);
    }
    options.sort(() => Math.random() - 0.5);
    createBalloons(options, false);

  } else {
    // 關卡二：聽詞拼音 — 選出正確的聲母/韻母
    const dictKeys = Object.keys(SPELLING_DICT);
    const targetComb = dictKeys[Math.floor(Math.random() * dictKeys.length)];
    const targetItem = SPELLING_DICT[targetComb];
    const parts   = targetComb.split("|");
    const initAns = parts[0];
    const medAns  = parts[1];
    const finAns  = parts[2];
    const toneAns = parts[3];

    gameState.currentQuestion = {
      type: "spelling", answer: targetComb,
      initAns, medAns, finAns, toneAns
    };

    speak(`請拼出，${targetItem.detail}，的，${targetItem.word}`);
    renderSpellingChallengeUI(targetItem, { initAns, medAns, finAns, toneAns });
  }
}

function createBalloons(options, isTone) {
  const area = document.getElementById("game-canvas-area");
  area.className = "balloon-layout";
  options.forEach((opt, idx) => {
    const balloon = document.createElement("div");
    balloon.className = `balloon balloon-color-${(idx % 4) + 1}`;
    const displayVal = isTone ? getToneDisplay(opt) : opt;
    balloon.innerHTML = `<span class="balloon-val">${displayVal}</span>`;
    balloon.addEventListener("click", () => { unlockAudio(); checkAnswer(opt); });
    area.appendChild(balloon);
  });
}

function renderSpellingChallengeUI(targetItem, ans) {
  const area = document.getElementById("game-canvas-area");
  area.className = "spelling-layout";

  area.innerHTML = `
    <div class="spelling-question-card">
      <div class="q-word">${targetItem.word}</div>
      <div class="q-svg">${targetItem.svg}</div>
      <div class="q-detail">${targetItem.detail}</div>
    </div>
    <div class="spelling-slots">
      <div class="slot" id="slot-init">聲母</div>
      <div class="slot" id="slot-med">介音</div>
      <div class="slot" id="slot-fin">韻母</div>
      <div class="slot" id="slot-tone">聲調</div>
    </div>
    <div class="spelling-btn-panel">
      <button class="submit-btn" onclick="submitSpellingChallengeAnswer()">拼好了！🤖</button>
    </div>
    <div class="challenge-keyboard">
      <div class="c-keys-col col-init" id="c-init-keys"></div>
      <div class="c-keys-col col-med"  id="c-med-keys"></div>
      <div class="c-keys-col col-fin"  id="c-fin-keys"></div>
      <div class="c-keys-col col-tone" id="c-tone-keys"></div>
    </div>
  `;

  window.challengeState = { initial: "", medial: "", final: "", tone: "1" };

  // 聲母候選 (含正確答案 + 隨機干擾)
  const initKeys = document.getElementById("c-init-keys");
  initKeys.innerHTML = `<button class="c-key-btn empty-btn" onclick="setChallengeSlot('initial','-')">無</button>`;
  const initPool = Object.keys(ZHUYIN_DB).filter(k => ZHUYIN_DB[k].category === "initial");
  getRandomOptions(initPool, ans.initAns, 3).forEach(k => {
    initKeys.innerHTML += `<button class="c-key-btn btn-init" id="ckey-i-${k}" onclick="setChallengeSlot('initial','${k}')">${k}</button>`;
  });

  // 介音候選
  const medKeys = document.getElementById("c-med-keys");
  medKeys.innerHTML = `<button class="c-key-btn empty-btn" onclick="setChallengeSlot('medial','-')">無</button>`;
  const medPool = Object.keys(ZHUYIN_DB).filter(k => ZHUYIN_DB[k].category === "medial");
  getRandomOptions(medPool, ans.medAns, 2).forEach(k => {
    medKeys.innerHTML += `<button class="c-key-btn btn-med" id="ckey-m-${k}" onclick="setChallengeSlot('medial','${k}')">${k}</button>`;
  });

  // 韻母候選
  const finKeys = document.getElementById("c-fin-keys");
  finKeys.innerHTML = `<button class="c-key-btn empty-btn" onclick="setChallengeSlot('final','-')">無</button>`;
  const finPool = Object.keys(ZHUYIN_DB).filter(k => ZHUYIN_DB[k].category === "final");
  getRandomOptions(finPool, ans.finAns, 3).forEach(k => {
    finKeys.innerHTML += `<button class="c-key-btn btn-fin" id="ckey-f-${k}" onclick="setChallengeSlot('final','${k}')">${k}</button>`;
  });

  // 聲調候選
  const toneKeys = document.getElementById("c-tone-keys");
  toneKeys.innerHTML = "";
  TONES.forEach(tone => {
    toneKeys.innerHTML += `<button class="c-key-btn btn-tone" id="cktone-${tone.symbol}" onclick="setChallengeSlot('tone','${tone.symbol}')">${tone.display}</button>`;
  });
}

function getRandomOptions(sourceArray, answer, maxWrongCount) {
  // answer 可能是 "-"（代表無）
  const answerIsBlank = !answer || answer === "-";
  let list = answerIsBlank ? [] : [answer];
  const remaining = sourceArray.filter(x => x !== answer);
  remaining.sort(() => Math.random() - 0.5);
  for (let i = 0; i < Math.min(maxWrongCount, remaining.length); i++) {
    list.push(remaining[i]);
  }
  return list.sort(() => Math.random() - 0.5);
}

function setChallengeSlot(type, value) {
  unlockAudio();
  window.challengeState[type] = value;

  if (value !== "" && value !== "-") {
    if (type === "tone") {
      const toneObj = TONES.find(t => t.symbol === value);
      if (toneObj) speak(toneObj.audioText);
    } else {
      speak(value);
    }
  }

  const slotMap = { initial: "slot-init", medial: "slot-med", final: "slot-fin", tone: "slot-tone" };
  const slot = document.getElementById(slotMap[type]);
  if (slot) {
    const labelMap = { initial: "聲母", medial: "介音", final: "韻母", tone: "聲調" };
    if (value === "" || value === "-") {
      slot.innerText = labelMap[type];
      slot.classList.remove("filled");
    } else {
      slot.innerText = type === "tone" ? getToneDisplay(value) : value;
      slot.classList.add("filled");
    }
  }

  // 高亮選中按鈕
  const colMap = { initial: "c-init-keys", medial: "c-med-keys", final: "c-fin-keys", tone: "c-tone-keys" };
  const container = document.getElementById(colMap[type]);
  if (container) {
    Array.from(container.getElementsByTagName("button")).forEach(btn => btn.classList.remove("active"));
    if (value === "" || value === "-") {
      container.getElementsByTagName("button")[0].classList.add("active");
    } else {
      const prefix = { initial: "ckey-i-", medial: "ckey-m-", final: "ckey-f-", tone: "cktone-" }[type];
      const btn = document.getElementById(`${prefix}${value}`);
      if (btn) btn.classList.add("active");
    }
  }
}

function submitSpellingChallengeAnswer() {
  unlockAudio();
  const q = gameState.currentQuestion;
  const cs = window.challengeState;
  const userKey = `${cs.initial||"-"}|${cs.medial||"-"}|${cs.final||"-"}|${cs.tone||"1"}`;
  if (userKey === q.answer) {
    handleAnswerSuccess();
  } else {
    handleAnswerFail();
  }
}

function checkAnswer(selectedOpt) {
  if (selectedOpt === gameState.currentQuestion.answer) {
    handleAnswerSuccess();
  } else {
    handleAnswerFail();
  }
}

function handleAnswerSuccess() {
  speak("答對了！你真棒！");
  gameState.stars += 1;
  updateStars();
  triggerConfetti();

  const area = document.getElementById("game-canvas-area");
  const card = document.createElement("div");
  card.className = "success-popup-card";
  card.innerHTML = `<div class="success-emoji">🎉 答對囉！</div><div class="success-msg">你太厲害了！得到一顆星星⭐</div>`;
  area.appendChild(card);

  setTimeout(() => nextBalloonQuestion(), 2800);
}

function handleAnswerFail() {
  speak("再試試看喔！你可以的！");

  // 給答錯視覺回饋（短暫抖動）
  const area = document.getElementById("game-canvas-area");
  area.style.animation = "shake 0.4s ease";
  setTimeout(() => area.style.animation = "", 500);
}

// ==========================================
// 輕量級 Confetti 五彩紙花特效
// ==========================================
function triggerConfetti() {
  const canvas = document.getElementById("confetti-canvas");
  if (!canvas) return;
  const ctx = canvas.getContext("2d");
  canvas.width  = window.innerWidth;
  canvas.height = window.innerHeight;
  canvas.style.display = "block";

  const colors = ["#FFC0CB", "#FFB84D", "#60A5FA", "#34D399", "#A78BFA", "#F472B6"];
  const particles = Array.from({ length: 160 }, () => ({
    x: Math.random() * canvas.width,
    y: Math.random() * canvas.height - canvas.height,
    r: Math.random() * 7 + 4,
    d: Math.random() * canvas.height,
    color: colors[Math.floor(Math.random() * colors.length)],
    tiltAngle: 0,
    tiltAngleIncremental: Math.random() * 0.07 + 0.02
  }));

  let animId;
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    let anyActive = false;
    particles.forEach((p, i) => {
      p.tiltAngle += p.tiltAngleIncremental;
      p.y += (Math.cos(p.d) + 3 + p.r / 2) / 2;
      p.x += Math.sin(p.tiltAngle);
      const tilt = Math.sin(p.tiltAngle - i / 3) * 15;
      if (p.y < canvas.height) anyActive = true;
      ctx.beginPath();
      ctx.lineWidth  = p.r;
      ctx.strokeStyle = p.color;
      ctx.moveTo(p.x + tilt + p.r / 2, p.y);
      ctx.lineTo(p.x + tilt, p.y + tilt + p.r / 2);
      ctx.stroke();
    });
    if (anyActive) {
      animId = requestAnimationFrame(draw);
    } else {
      canvas.style.display = "none";
      cancelAnimationFrame(animId);
    }
  }
  draw();
}

// ==========================================
// 介面導覽控制
// ==========================================
function switchMode(mode) {
  unlockAudio();
  currentMode = mode;

  Array.from(document.getElementsByClassName("nav-btn")).forEach(btn => btn.classList.remove("active"));
  document.getElementById(`nav-${mode}`).classList.add("active");

  Array.from(document.getElementsByClassName("mode-panel")).forEach(p => p.style.display = "none");
  document.getElementById(`panel-${mode}`).style.display = "block";

  if      (mode === "keyboard") renderKeyboard();
  else if (mode === "robot")    renderRobot();
  else if (mode === "game")     startBalloonGame();
}

function enterAdventure() {
  unlockAudio();
  document.getElementById("welcome-screen").style.display = "none";
  document.getElementById("app-main").style.display = "block";
  switchMode("keyboard");
}

window.addEventListener("DOMContentLoaded", () => {
  initSpeech();
  if ("serviceWorker" in navigator) {
    navigator.serviceWorker.register("./sw.js")
      .then(reg => console.log("SW Registered:", reg))
      .catch(err => console.warn("SW Failed:", err));
  }
});
